const states = {
  idle:    { start: (p) => { p.state = states.running; } },
  running: { start: () => {}, stop: (p) => { p.state = states.idle; } },
};

class Player {
  constructor() { this.state = states.idle; }
  start() { this.state.start(this); }   // delegation, no inheritance
}

variants.code_sketch:
const states = {
  idle:    { start: (p) => { p.state = states.running; } },
  running: { start: () => {}, stop: (p) => { p.state = states.idle; } },
};

class Player {
  constructor() { this.state = states.idle; }
  start() { this.state.start(this); }   // delegation, no inheritance
}

import { createMachine, createActor } from "xstate";

const player = createMachine({
  initial: "idle",
  states: {
    idle:    { on: { START: "running" } },
    running: { on: { STOP: "idle" } },
  },
});

const actor = createActor(player).start();
actor.send({ type: "START" });
